Look lookRun(int id) {
  Look k = lookStart();
  switch (id) {
    case 0: look_0(k); break;
    case 1: look_1(k); break;
    case 2: look_2(k); break;
    case 3: look_3(k); break;
    case 4: look_4(k); break;
    case 5: look_5(k); break;
  }
  if (lookDebug > 0.5) {
    switch (id) {
      case 0: k.colour = vec3(0.02315336617811041, 0.02315336617811041, 0.0295568344378088); break;
      case 1: k.colour = vec3(0.26635560480286247, 0.2788942634768104, 0.30946892281750854); break;
      case 2: k.colour = vec3(0.6866853124353135, 0.7011018919329731, 0.7156935005064807); break;
      case 3: k.colour = vec3(0.006995410187265387, 0.006995410187265387, 0.008023192985384994); break;
      case 4: k.colour = vec3(0.6239603916750761, 0.6514056374198242, 0.7011018919329731); break;
      case 5: k.colour = vec3(0.32314320911295075, 0.33716361504833037, 0.3662525955988395); break;
    }
  }
  return k;
}
